const MARGIN = { top: 8, right: 8, bottom: 8, left: 8 };

// The airports are lower 48 only, so Alaska and Hawaii are dropped rather than left as
// insets that would be tiled by cells belonging to mainland airports.
const lower48: FeatureCollection = {
  type: 'FeatureCollection',
  features: usStates.filter((d) => d.id !== '02' && d.id !== '15')
};

type Cell = { iata: string; title: string; x: number; y: number; outline: string };

/** One site per airport. The state outlines beneath are basemap, not data. */
export type Data = Array<
  [longitude: number, latitude: number, iata: string, name: string, city: string, state: string]
>;

export default function UsAirportsVoronoi({ data = usAirports, width }:
  { data?: Data; width: number }) {
  const height = Math.round(width * 0.62);
  const innerWidth = Math.max(1, width - MARGIN.left - MARGIN.right);
  const innerHeight = Math.max(1, height - MARGIN.top - MARGIN.bottom);
  const clipId = `airports-voronoi-${useId().replace(/:/g, '')}`;

  const { path, land, projection } = useMemo(() => {
    const projection = d3.geoAlbersUsa().fitSize([innerWidth, innerHeight], lower48);
    const path = d3.geoPath(projection);
    // One compound path of disjoint states: its union is the nation outline, which both
    // fills the basemap and clips the cells without merging the topology by hand.
    const land = lower48.features.map((d) => path(d) ?? '').join('');
    return { path, land, projection };
  }, [innerWidth, innerHeight]);

  // The diagram is built from projected pixels, not lon/lat: d3.Delaunay is planar, and
  // Albers bends meridians enough that raw coordinates would give the wrong neighbours.
  const cells = useMemo(() => {
    const sites = data.flatMap(([lon, lat, iata, name, city, state]) => {
      const point = projection([lon, lat]);
      return point ? [{ iata, title: `${name} Airport\n${city}, ${state}`, point }] : [];
    });

    const voronoi = d3.Delaunay.from(
      sites,
      (d) => d.point[0],
      (d) => d.point[1]
    ).voronoi([0, 0, innerWidth, innerHeight]);

    return sites.flatMap((site, index): Cell[] => {
      const outline = voronoi.renderCell(index);
      if (!outline) return [];
      return [
        { iata: site.iata, title: site.title, x: site.point[0], y: site.point[1], outline }
      ];
    });
  }, [data, projection, innerWidth, innerHeight]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Voronoi diagram of United States airports, where each cell is the region closest to one airport"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <defs>
          <clipPath id={clipId}>
            <path d={land} />
          </clipPath>
        </defs>

        <path d={land} fill="var(--line)" />
        <path
          d={path(usStateBorders) ?? undefined}
          fill="none"
          stroke="var(--bg)"
          strokeLinejoin="round"
        />

        <g
          clipPath={`url(#${clipId})`}
          fill="none"
          stroke="var(--accent)"
          strokeWidth={0.6}
          strokeOpacity={0.75}
        >
          {cells.map((cell) => (
            <path key={cell.iata} d={cell.outline}>
              <title>{cell.title}</title>
            </path>
          ))}
        </g>

        <g fill="var(--text)">
          {cells.map((cell) => (
            <circle key={cell.iata} cx={cell.x} cy={cell.y} r={1.5} />
          ))}
        </g>
      </g>
    </svg>
  );
}
